// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LionsLounge {
    function getOwner() external view returns (address);
    function blacklistAddress(address _address, bool _value) external;
    function isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);
    address victim = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        victim = address(0x123);
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the owner address
        address owner = LionsLounge(TARGET).getOwner();

        // Impersonate the owner
        vm.prank(owner);

        // Call blacklistAddress to blacklist the victim
        LionsLounge(TARGET).blacklistAddress(victim, true);

        // Verify the victim is now blacklisted
        bool isBlacklisted = LionsLounge(TARGET).isBlacklisted(victim);
        assertEq(isBlacklisted, true, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

